const p = $json;

const keywords = [
  p.title,
  p.handle,
  ...(p.tags || []).map(t => t.value),
  ...(p.variants || []).map(v => v.title),
  ...(p.options || []).flatMap(o => o.values.map(v => v.value))
].filter(Boolean);

const attributes = {
  material: p.material,
  origin_country: p.origin_country,
  weight: p.weight
};

const variants = (p.variants || []).map(v => {
  return `- ${v.title} (SKU: ${v.sku || "N/A"}, Barcode: ${v.barcode || "N/A"})`;
}).join("\n");

const options = (p.options || []).map(o => {
  return `- ${o.title}: ${o.values.map(v => v.value).join(", ")}`;
}).join("\n");

const content = `
[PRODUCT]
ID: ${p.id}
TITLE: ${p.title}
HANDLE: ${p.handle}

[DESCRIPTION]
${p.description || "No description available"}

[KEYWORDS]
${keywords.join(", ")}

[ATTRIBUTES]
${JSON.stringify(attributes, null, 2)}

[OPTIONS]
${options}

[VARIANTS]
${variants}

[SEARCH_HINTS]
${p.title} ${keywords.join(" ")} buy ${p.title} price Philippines LPG canister refill gas
`;

return [{
  json: {
    id: p.id,
    content,
    metadata: {
      title: p.title,
      handle: p.handle
    }
  }
}];

return [{
  json: {
    id: $json.id,
    embedding: $json.embedding,
    content: $node["Build RAG Content"].json.content,
    metadata: $node["Build RAG Content"].json.metadata
  }
}];
